import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import {
  uv,
  vec3,
  vec4,
  mix,
  step,
  float,
  uniform,
  positionLocal,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, Shape, ExtrudeGeometry, PlaneGeometry, DirectionalLight, Color } = ctx.THREE;

  const group = new Group();
  group.name = 'gradient-cta';

  const colors = config.intent?.visualSpec?.colors ?? config.visualSpec?.colors ?? {};
  const stops = colors.gradientStops ?? [
    { at: 0, hex: '#ff4450' },
    { at: 0.55, hex: '#ff2a38' },
    { at: 1, hex: '#c1121f' },
  ];
  const accent = colors.accent ?? '#ff2a38';
  const paper = colors.paper ?? '#e8ecf2';
  const background = colors.background ?? '#0b0b10';

  const cTop = new Color(stops[0].hex);
  const cMid = new Color(stops[1].hex);
  const cBot = new Color(stops[2].hex);
  const cAccent = new Color(accent);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let ctaText = 'BEGIN COMMISSION';
  let capText = 'NO DEPOSIT REQUIRED';
  for (const item of items) {
    if (item.role === 'cta-label') ctaText = item.text;
    else if (item.role === 'caption') capText = item.text;
  }

  const disposables = [];
  const timelines = [];

  // ---- Backdrop stage plane (vertical gradient) ----
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  {
    const vy = uv().y;
    const surf = vec3(new Color(colors.surface ?? '#16161d').convertSRGBToLinear());
    const back = vec3(new Color(background).convertSRGBToLinear());
    bgMat.colorNode = mix(back, surf, vy.mul(0.7).add(0.15));
  }
  const bg = new Mesh(bgGeo, bgMat);
  bg.position.set(0, 0, -2.5);
  group.add(bg);
  disposables.push(bgGeo, bgMat);

  // ---- Rounded-rect extruded button ----
  const W = 2.6, H = 0.68, R = 0.08, DEPTH = 0.03;
  function roundedRect(w, h, r) {
    const s = new Shape();
    const x = -w / 2, y = -h / 2;
    s.moveTo(x + r, y);
    s.lineTo(x + w - r, y);
    s.quadraticCurveTo(x + w, y, x + w, y + r);
    s.lineTo(x + w, y + h - r);
    s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    s.lineTo(x + r, y + h);
    s.quadraticCurveTo(x, y + h, x, y + h - r);
    s.lineTo(x, y + r);
    s.quadraticCurveTo(x, y, x + r, y);
    return s;
  }

  const btnGeo = new ExtrudeGeometry(roundedRect(W, H, R), {
    depth: DEPTH,
    bevelEnabled: true,
    bevelThickness: 0.03,
    bevelSize: 0.025,
    bevelSegments: 2,
  });
  btnGeo.center();

  const btnMat = new MeshStandardNodeMaterial();
  btnMat.roughness = 0.5;
  btnMat.metalness = 0.35;
  btnMat.clearcoat = 0.22;

  const edgeIntensity = uniform(1.6);
  {
    const topL = vec3(cTop.clone().convertSRGBToLinear());
    const midL = vec3(cMid.clone().convertSRGBToLinear());
    const botL = vec3(cBot.clone().convertSRGBToLinear());
    const vy = uv().y;
    // top->mid over 0..0.55, mid->bot over 0.55..1, from top of face
    const t = float(1.0).sub(vy);
    const upper = mix(topL, midL, t.div(0.55).clamp(0, 1));
    const lower = mix(midL, botL, t.sub(0.55).div(0.45).clamp(0, 1));
    const grad = mix(upper, lower, step(0.55, t));
    // hard seam line at 50% face height
    const seam = step(0.495, vy).mul(step(vy, 0.505));
    const face = mix(grad, grad.mul(0.55), seam);
    btnMat.colorNode = face;

    // perimeter emissive edge — glow near local extremes of geometry
    const accL = vec3(cAccent.clone().convertSRGBToLinear());
    const edgeU = uv().x;
    const rim = step(0.985, edgeU).add(step(edgeU, 0.015))
      .add(step(0.985, vy)).add(step(vy, 0.015)).clamp(0, 1);
    btnMat.emissiveNode = accL.mul(rim.mul(edgeIntensity));
  }

  const button = new Mesh(btnGeo, btnMat);
  button.position.set(0, 0.12, 0);
  group.add(button);
  disposables.push(btnGeo, btnMat);

  // ---- Node-local lights ----
  const key = new DirectionalLight(0xffffff, 1.2);
  key.position.set(-2.5, 3, 4);
  group.add(key);
  const rim = new DirectionalLight(cAccent.getHex(), 0.9);
  rim.position.set(3, -1, -2);
  group.add(rim);

  // ---- Contact shadow ----
  const shadowGeo = new PlaneGeometry(W * 1.15, H * 1.3);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  {
    const d = uv().sub(0.5).length().mul(2.0);
    const a = float(1.0).sub(d.clamp(0, 1)).pow(1.5).mul(0.35);
    shadowMat.colorNode = vec4(vec3(0.0), a);
  }
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, 0.12 - H / 2 - 0.02, -0.08);
  group.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---- Text ----
  const label = ctx.fontAtlas.createText(ctaText, {
    fontSize: 40,
    color: paper,
    align: 'center',
    letterSpacingPx: 5,
  });
  label.position.set(0, 0.12, DEPTH + 0.06);
  group.add(label);

  const caption = ctx.fontAtlas.createText(capText, {
    fontSize: 18,
    color: paper,
    align: 'center',
    letterSpacingPx: 4,
  });
  caption.position.set(0, 0.12 - H / 2 - 0.22, 0.02);
  group.add(caption);

  // ---- Mount motion: weighted-settle ----
  group.scale.setScalar(1.04);
  const settleTl = gsap.timeline();
  settleTl.to(group.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  timelines.push(settleTl);

  // ---- Interaction handlers ----
  let hoverTl = null;
  let pressTl = null;

  group.userData.handlers = {
    hover: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(button.position, { z: 0.06, duration: 0.18, ease: 'power2.out' }, 0);
      hoverTl.to(edgeIntensity, { value: 2.2, duration: 0.18, ease: 'power2.out' }, 0);
      timelines.push(hoverTl);
    },
    unhover: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(button.position, { z: 0, duration: 0.18, ease: 'power2.out' }, 0);
      hoverTl.to(edgeIntensity, { value: 1.6, duration: 0.18, ease: 'power2.out' }, 0);
      timelines.push(hoverTl);
    },
    click: () => {
      if (pressTl) pressTl.kill();
      pressTl = gsap.timeline({
        onComplete: () => ctx.emit('navigate', { to: 'hub-pricing' }),
      });
      pressTl.to(group.scale, {
        x: 0.97, y: 0.97, z: 0.97,
        duration: 0.12,
        ease: 'back.out(2)',
      });
      pressTl.to(shadow.scale, { x: 0.85, y: 0.85, duration: 0.12, ease: 'power2.out' }, 0);
      pressTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.24, ease: 'power3.out' });
      pressTl.to(shadow.scale, { x: 1, y: 1, duration: 0.24, ease: 'power3.out' }, '<');
      timelines.push(pressTl);
    },
  };

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl && tl.kill());
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    disposables.forEach((d) => d && d.dispose && d.dispose());
    if (label.userData?.cleanup) label.userData.cleanup();
    if (caption.userData?.cleanup) caption.userData.cleanup();
  };

  return group;
}
